abstract class ProductBase {
    protected final String id;
    ProductBase(String id) { this.id = id; System.out.println("base:" + id); }
}
class OrthoProduct extends ProductBase {
    OrthoProduct(String id) { super(id); System.out.println("child:" + id); }
}
public class AbstractConstructorDemo {
    public static void main(String[] args) { new OrthoProduct("O1"); }
}
